}

set_config_port() {   # $1 = config.json, $2 = í¬íŠ¸ (ë‹¤ë¥¸ ì„¤ì •ì€ ê·¸ëŒ€ë¡œ ë‘ )
  "$PY" - "$1" "$2" <<'EOF' || die "config.jsonì— í¬íŠ¸ë¥¼ ì“°ì§€ ëª»í–ˆìŠµë‹ˆë‹¤."
import json, sys
from collections import OrderedDict
